import{_ as o,o as a,c as r,ag as e}from"./chunks/framework.CAXxHpAX.js";const p=JSON.parse('{"title":"对境不住","description":"","frontmatter":{},"headers":[],"relativePath":"10-核心模型/model-对境不住.md","filePath":"10-核心模型/model-对境不住.md","lastUpdated":1778033203000}'),l={name:"10-核心模型/model-对境不住.md"};function n(i,t,u,s,h,q){return a(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="对境不住" tabindex="-1">对境不住 <a class="header-anchor" href="#对境不住" aria-label="Permalink to &quot;对境不住&quot;">​</a></h1><blockquote><p>了空居士智慧体系第一心法。 不被现象所迷惑，保持最清净的心去看待一切。</p></blockquote><hr><h2 id="核心内涵" tabindex="-1">核心内涵 <a class="header-anchor" href="#核心内涵" aria-label="Permalink to &quot;核心内涵&quot;">​</a></h2><p><strong>对境不住</strong> 是了空居士教导中最核心的心法。它不是排斥念头、逃避现象，而是<strong>客观地面对一切现象而不被情绪扰动</strong>，如同明镜照物，物来不拒，物去不留。</p><p>和相邻模型的边界：</p><ul><li><strong>对法不执</strong>：对境不住是对&quot;外面发生的事&quot;不动心，对法不执是对&quot;学到的方法&quot;不执着</li><li><strong>历境炼心</strong>：对境不住是&quot;防守&quot;（保持清净不被扰动），历境炼心是&quot;进攻&quot;（把烦恼转化为觉悟）</li></ul><hr><h2 id="关键原子" tabindex="-1">关键原子 <a class="header-anchor" href="#关键原子" aria-label="Permalink to &quot;关键原子&quot;">​</a></h2><h3 id="一、核心心法-心怎么放" tabindex="-1">一、核心心法：心怎么放 <a class="header-anchor" href="#一、核心心法-心怎么放" aria-label="Permalink to &quot;一、核心心法：心怎么放&quot;">​</a></h3><h4 id="_1-无所住生心" tabindex="-1">1. 无所住生心 <a class="header-anchor" href="#_1-无所住生心" aria-label="Permalink to &quot;1. 无所住生心&quot;">​</a></h4><p><strong>原文</strong>：《金刚经》的核心就是&quot;应无所住而生其心&quot;。</p><p><strong>解读</strong>：&quot;无所住&quot;是不执着于任何事物，&quot;生心&quot;是正常地应对、了知。两者不矛盾——不执着不等于不知道，知道不等于要执着。了空居士概括为：<strong>不被现象所迷惑，保持最清净的心去看待一切。</strong></p><blockquote><p>完整原文：<a href="/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></p></blockquote><h4 id="_2-心如明镜" tabindex="-1">2. 心如明镜 <a class="header-anchor" href="#_2-心如明镜" aria-label="Permalink to &quot;2. 心如明镜&quot;">​</a></h4><p><strong>原文</strong>：心如明镜，照物而不染。</p><p><strong>解读</strong>：镜子照见万物，但它们不会被镜子&quot;吸收&quot;。心也应如此——看到、知道、应对，但不被所看到的东西污染。</p><blockquote><p>完整原文：<a href="/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></p></blockquote><h4 id="_3-离相" tabindex="-1">3. 离相 <a class="header-anchor" href="#_3-离相" aria-label="Permalink to &quot;3. 离相&quot;">​</a></h4><p><strong>原文</strong>：凡所有相，皆是虚妄。若见诸相非相，即见如来。</p><p><strong>解读</strong>：有三个层次——</p><ul><li><strong>离相即客观</strong>：离相不是逃避，而是以最清净最客观的心去看待一切，包括看待自己。司马光砸缸——救人要紧，不管金鱼缸会不会被骂，这就是离相。</li><li><strong>虚妄不是没有</strong>：&quot;虚妄&quot;不是不存在，而是不永恒、会变化。这是个好消息——正因为会变化，我们才能通过努力让它变好。&quot;虚妄&quot;不是消极，是最积极的。</li><li><strong>不被现象&quot;绑住&quot;</strong>：看到、知道、应对，但不被表面现象迷惑。不是否定现象，而是在现象中保持自由。</li></ul><blockquote><p>完整原文：<a href="/60-原文段落/金刚经5分-离相">金刚经5分-离相</a></p></blockquote><hr><h3 id="二、对自我的态度-我执怎么破" tabindex="-1">二、对自我的态度：我执怎么破 <a class="header-anchor" href="#二、对自我的态度-我执怎么破" aria-label="Permalink to &quot;二、对自我的态度：我执怎么破&quot;">​</a></h3><h4 id="_4-无私心分别" tabindex="-1">4. 无私心分别 <a class="header-anchor" href="#_4-无私心分别" aria-label="Permalink to &quot;4. 无私心分别&quot;">​</a></h4><p><strong>原文</strong>：无分别是无私心分别，不是不辨是非。</p><p><strong>解读</strong>：很多人误解&quot;无分别心&quot;是什么都不分。了空居士纠正：走路该从门出去还是从墙壁出去？这需要分别。真正的无分别，是没有私心在作祟，客观如实地判断。</p><blockquote><p>完整原文：<a href="/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></p></blockquote><h4 id="_5-知见无见" tabindex="-1">5. 知见无见 <a class="header-anchor" href="#_5-知见无见" aria-label="Permalink to &quot;5. 知见无见&quot;">​</a></h4><p><strong>原文</strong>：知见无见，斯即涅槃，无漏真净。</p><p><strong>解读</strong>：不要带着任何成见去看问题和看自己。六祖对惠明说&quot;不思善不思恶，正与么时，那个是明上座的本来面目&quot;——没有成见的时候，佛性自然显现。</p><blockquote><p>完整原文：<a href="/60-原文段落/金刚经3分-四相与无我">金刚经3分-四相与无我</a></p></blockquote><h4 id="_6-四相与无我" tabindex="-1">6. 四相与无我 <a class="header-anchor" href="#_6-四相与无我" aria-label="Permalink to &quot;6. 四相与无我&quot;">​</a></h4><p><strong>原文</strong>：若菩萨有我相、人相、众生相、寿者相，即非菩萨。</p><p><strong>原文</strong>：一切法无我、无人、无众生、无寿者。</p><p><strong>解读</strong>：只要执着于自我、他人、众生、时间这些概念，就不是真菩萨。度了无量众生，心中却觉得&quot;实无众生得灭度者&quot;——做了但不觉得&quot;我在做&quot;。更进一步，不执着于&quot;我在修行&quot;&quot;我在度众生&quot;&quot;我达到了什么境界&quot;——这些念头一起，就已经偏离了清净心。</p><blockquote><p>完整原文：<a href="/60-原文段落/金刚经3分-四相与无我">金刚经3分-四相与无我</a></p></blockquote><h4 id="_7-无我不等于没有" tabindex="-1">7. 无我不等于没有 <a class="header-anchor" href="#_7-无我不等于没有" aria-label="Permalink to &quot;7. 无我不等于没有&quot;">​</a></h4><p><strong>原文</strong>：无我是无私心妄想，不是人消失。</p><p><strong>解读</strong>：很多人以为&quot;无我&quot;就是人没有了，堕入空的邪见。无我是无私心妄想，一切都是般若智慧的流露——该吃饭吃饭，该做事做事，只是没有贪嗔痴慢疑。</p><blockquote><p>完整原文：<a href="/60-原文段落/金刚经15分-信心不逆">金刚经15分-信心不逆</a></p></blockquote><hr><h3 id="三、心的运作机制" tabindex="-1">三、心的运作机制 <a class="header-anchor" href="#三、心的运作机制" aria-label="Permalink to &quot;三、心的运作机制&quot;">​</a></h3><h4 id="_8-定慧等持" tabindex="-1">8. 定慧等持 <a class="header-anchor" href="#_8-定慧等持" aria-label="Permalink to &quot;8. 定慧等持&quot;">​</a></h4><p><strong>原文</strong>：一心念佛本来就具足定慧。一心是定，念念分明是慧。</p><p><strong>解读</strong>：定和慧不是两件事。心静下来（定）的同时，了了分明（慧）也在。不要追求先定后慧，它们是同时的。</p><blockquote><p>完整原文：<a href="/60-原文段落/定慧等持">定慧等持</a></p></blockquote><h4 id="_9-三昧即非有心非无心" tabindex="-1">9. 三昧即非有心非无心 <a class="header-anchor" href="#_9-三昧即非有心非无心" aria-label="Permalink to &quot;9. 三昧即非有心非无心&quot;">​</a></h4><p><strong>原文</strong>：正入定时就不见有无之心，不是有心入也不是无心入。</p><p><strong>解读</strong>：真正的定境，不是强行让自己&quot;入定&quot;，也不是放任自己散漫。是自然而然地进入一种身心宁静的状态。</p><blockquote><p>完整原文：<a href="/60-原文段落/答疑2014-三昧即正受">答疑2014-三昧即正受</a></p></blockquote><h4 id="_10-三心不可得" tabindex="-1">10. 三心不可得 <a class="header-anchor" href="#_10-三心不可得" aria-label="Permalink to &quot;10. 三心不可得&quot;">​</a></h4><p><strong>原文</strong>：过去心不可得，现在心不可得，未来心不可得。</p><p><strong>解读</strong>：心念刹那刹那在变化，没有一个固定的&quot;心&quot;可以抓住。过去已去，未来未至，现在无住。这不是消极，而是告诉你——不要被任何一时的念头困住。当你发现自己正在纠结某件事，意识到&quot;这个纠结也会过去&quot;——那就是解脱的开始。</p><blockquote><p>完整原文：<a href="/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></p></blockquote><h4 id="_11-无实无虚" tabindex="-1">11. 无实无虚 <a class="header-anchor" href="#_11-无实无虚" aria-label="Permalink to &quot;11. 无实无虚&quot;">​</a></h4><p><strong>原文</strong>：如来所得阿耨多罗三藐三菩提，于是中无实无虚。</p><p><strong>解读</strong>：清净心的境界，既没有一个具体的东西可以执着（无实），也不是一片空白（无虚）。高兴知道高兴，但不执着高兴；悲伤知道悲伤，但不执着悲伤。一切了了分明，但心不动摇。</p><blockquote><p>完整原文：<a href="/60-原文段落/金刚经17分-于法无所得">金刚经17分-于法无所得</a></p></blockquote><hr><h3 id="四、在行动中落实" tabindex="-1">四、在行动中落实 <a class="header-anchor" href="#四、在行动中落实" aria-label="Permalink to &quot;四、在行动中落实&quot;">​</a></h3><h4 id="_12-无所住行布施" tabindex="-1">12. 无所住行布施 <a class="header-anchor" href="#_12-无所住行布施" aria-label="Permalink to &quot;12. 无所住行布施&quot;">​</a></h4><p><strong>原文</strong>：菩萨于法，应无所住行于布施。</p><p><strong>解读</strong>：做任何事情都不带私心目的，大公无私坦坦荡荡。看到路上有石头碍事，很自然地搬开——不为了给人看，不为了求表扬。</p><blockquote><p>完整原文：<a href="/60-原文段落/金刚经4分-无所住行布施">金刚经4分-无所住行布施</a></p></blockquote><h4 id="_13-离欲即不贪著" tabindex="-1">13. 离欲即不贪著 <a class="header-anchor" href="#_13-离欲即不贪著" aria-label="Permalink to &quot;13. 离欲即不贪著&quot;">​</a></h4><p><strong>原文</strong>：离欲就是不贪著，不是断绝。</p><p><strong>解读</strong>：吃饭穿衣是正常的，不挑剔、不贪恋就好。古代有人将&quot;离欲&quot;解为&quot;断绝一切欲望&quot;，这是错的。佛祖也托钵吃饭，示现正常生活。</p><blockquote><p>完整原文：<a href="/60-原文段落/金刚经9分-离欲与一相无相">金刚经9分-离欲与一相无相</a></p></blockquote><h4 id="_14-一相无相" tabindex="-1">14. 一相无相 <a class="header-anchor" href="#_14-一相无相" aria-label="Permalink to &quot;14. 一相无相&quot;">​</a></h4><p><strong>原文</strong>：一相无相——任何一个现象都没有一个永恒不变的自我。</p><p><strong>解读</strong>：山不是永恒的山，海不是永恒的海，一切都在变化中。放下&quot;必须永恒&quot;的执念，心就轻松了。</p><blockquote><p>完整原文：<a href="/60-原文段落/金刚经9分-离欲与一相无相">金刚经9分-离欲与一相无相</a></p></blockquote><hr><h3 id="五、业障与清净心" tabindex="-1">五、业障与清净心 <a class="header-anchor" href="#五、业障与清净心" aria-label="Permalink to &quot;五、业障与清净心&quot;">​</a></h3><h4 id="_15-业障与清净心" tabindex="-1">15. 业障与清净心 <a class="header-anchor" href="#_15-业障与清净心" aria-label="Permalink to &quot;15. 业障与清净心&quot;">​</a></h4><p><strong>原文</strong>：以今世人轻贱故，先世罪业即为消灭。</p><p><strong>原文</strong>：了即业障本来空，未了还需还宿债。</p><p><strong>解读</strong>：受持《金刚经》的人被人轻贱，不生嗔恚——这就是对境不住，业障在清净心中自然消融。真正彻悟的人，业障对他已无实质影响，如同大海能容纳一切污浊而不被污染——不是现象消失，而是本质不受影响。但未悟的人，还是要老实面对因果。业障不是定业，是可以化解的。</p><blockquote><p>完整原文：<a href="/60-原文段落/金刚经16分-业障与清净心">金刚经16分-业障与清净心</a></p></blockquote><hr><h3 id="六、操作方法" tabindex="-1">六、操作方法 <a class="header-anchor" href="#六、操作方法" aria-label="Permalink to &quot;六、操作方法&quot;">​</a></h3><h4 id="_16-理智-修行的操作手柄" tabindex="-1">16. 理智：修行的操作手柄 <a class="header-anchor" href="#_16-理智-修行的操作手柄" aria-label="Permalink to &quot;16. 理智：修行的操作手柄&quot;">​</a></h4><p><strong>原文</strong>：保持平静的要诀就是保持理智地去看待一切。</p><p><strong>解读</strong>：理智是&quot;知道道理&quot;和&quot;做到道理&quot;之间的桥梁。你知道要&quot;对境不住&quot;，但情绪上来的那一刻，是理智帮你按下暂停键——问自己&quot;我为什么不平静？这样正确吗？&quot;理智不是冷漠，是在情绪升起时依然能够做出正确判断的能力。韩信忍胯下之辱，不是不愤怒，是理智告诉他&quot;不忍后果更严重&quot;。日常修行中，每当情绪波动，第一时间启动理智——这就是对境不住的实操抓手。</p><blockquote><p>完整原文：<a href="/60-原文段落/金刚经5分-离相">金刚经5分-离相</a></p></blockquote><hr><h2 id="四步操作法" tabindex="-1">四步操作法 <a class="header-anchor" href="#四步操作法" aria-label="Permalink to &quot;四步操作法&quot;">​</a></h2><p>面对任何让你情绪波动的情境，按这四步走：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>情绪起来 →</span></span>
<span class="line"><span>  第一步 觉察 → 知道&quot;我在生气/焦虑/恐惧&quot;（不怕念起）</span></span>
<span class="line"><span>  第二步 暂停 → 启动理智，问自己&quot;我为什么不平静？这样正确吗？&quot;</span></span>
<span class="line"><span>  第三步 观照 → 像旁观者看河水流淌，看着情绪但不跳进去（心如明镜）</span></span>
<span class="line"><span>  第四步 放下 → 让它过去，不压着也不抓着（三心不可得）</span></span></code></pre></div><p><strong>日常训练（预防）和紧急处置（补救）分开练</strong>：</p><table tabindex="0"><thead><tr><th></th><th>预防（平常时）</th><th>补救（情绪爆发后）</th></tr></thead><tbody><tr><td><strong>练什么</strong></td><td>心如明镜、定慧等持——日常小事中练观照</td><td>不怕念起只怕觉迟——觉察到自己失控的那一刻就是转机</td></tr><tr><td><strong>怎么做</strong></td><td>每天找一件小事练习&quot;不跟情绪走&quot;</td><td>被扰动后不责备自己，立刻启动理智回到观照</td></tr><tr><td><strong>检验标准</strong></td><td>遇到不顺心的事，恢复平静的时间越来越短</td><td>失控后能不陷入自我谴责，直接回到&quot;下一步做什么&quot;</td></tr></tbody></table><hr><h2 id="常见失败诊断" tabindex="-1">常见失败诊断 <a class="header-anchor" href="#常见失败诊断" aria-label="Permalink to &quot;常见失败诊断&quot;">​</a></h2><p>了空居士经常指出学生在实践对境不住时的典型错误：</p><table tabindex="0"><thead><tr><th>错误状态</th><th>表现</th><th>为什么不是对境不住</th></tr></thead><tbody><tr><td><strong>压抑</strong></td><td>被骂了忍着不发火，心里咬牙切齿</td><td>外面没动，里面在翻腾。这不是清净，是憋着</td></tr><tr><td><strong>麻木</strong></td><td>&quot;无所谓&quot;&quot;随便&quot;挂在嘴边，对什么都不在意</td><td>不是不执着，是逃避。镜子照物是了了分明的，不是一片黑暗</td></tr><tr><td><strong>自我谴责</strong></td><td>&quot;我又起情绪了，我真差劲&quot;</td><td>在被扰动之上又多了一层&quot;对扰动的不接受&quot;——双重心结</td></tr><tr><td><strong>假装放下</strong></td><td>&quot;我已经放下了&quot;说很多遍</td><td>真放下不需要说。嘴上说放下的时候，心里还在抓着</td></tr><tr><td><strong>求清净</strong></td><td>拼命压住念头，期待&quot;没有念头&quot;的境界</td><td>最清净的人是死人。清净心不是没有念头，是不被念头带着跑</td></tr></tbody></table><hr><h2 id="实践指引" tabindex="-1">实践指引 <a class="header-anchor" href="#实践指引" aria-label="Permalink to &quot;实践指引&quot;">​</a></h2><h3 id="初阶-在小事上练-每天都可以做" tabindex="-1">初阶：在小事上练（每天都可以做） <a class="header-anchor" href="#初阶-在小事上练-每天都可以做" aria-label="Permalink to &quot;初阶：在小事上练（每天都可以做）&quot;">​</a></h3><ul><li>遇到让人生气的小事（堵车、排队被插队），试着做&quot;镜子&quot;——知道自己在生气，但不被气带走</li><li>遇到让人高兴的事，知道自己在高兴，但不沉溺其中、不反复回味</li><li>被人说了不好听的话，试着用旁观者的心态——&quot;他为什么这么激动？&quot;而不是&quot;他在骂我！&quot;</li><li>每天睡前回想一次：今天哪一次我没被情绪带走？（哪怕只有一次）</li></ul><h3 id="中阶-在情绪中保持在线" tabindex="-1">中阶：在情绪中保持在线 <a class="header-anchor" href="#中阶-在情绪中保持在线" aria-label="Permalink to &quot;中阶：在情绪中保持在线&quot;">​</a></h3><ul><li>和人争吵时，能不能一边生气一边还有一个&quot;旁观者&quot;在看着自己生气？</li><li>做任何事不带私心目的，像司马光砸缸——救人最重要，其他的不管</li><li>事情做完就放下，不在脑中反复回放&quot;我做得对不对&quot;</li></ul><h3 id="静坐中" tabindex="-1">静坐中 <a class="header-anchor" href="#静坐中" aria-label="Permalink to &quot;静坐中&quot;">​</a></h3><ul><li>杂念来了，看着它，不跟随，不抵制——这就是对境不住</li><li>不是要&quot;消除&quot;念头，而是不被念头牵着跑</li><li>腿麻、身体不适——知道它在麻，但不跟&quot;好难受&quot;&quot;坚持不住了&quot;的念头走</li></ul><h3 id="检验标准-你怎么知道自己进步了" tabindex="-1">检验标准（你怎么知道自己进步了） <a class="header-anchor" href="#检验标准-你怎么知道自己进步了" aria-label="Permalink to &quot;检验标准（你怎么知道自己进步了）&quot;">​</a></h3><ul><li><strong>初阶标志</strong>：被扰动后能在 1 分钟内回到平静</li><li><strong>中阶标志</strong>：被扰动时心里同时有一个&quot;旁观者&quot;存在</li><li><strong>高阶标志</strong>：大部分事情已经扰动不了你，不是麻木，而是自然地平静</li></ul><blockquote><p><strong>用 <a href="/meta-整体观">整体观</a></strong>：眼前的困难只是一个&quot;相&quot;，放到一生、放到三世中看，就没那么大了。不被局部现象迷惑。</p></blockquote><hr><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对法不执">对法不执</a> — 对境不住是&quot;对外面的事不动心&quot;，对法不执是&quot;对学到的方法不执着&quot;</li><li><a href="/10-核心模型/model-天人合一">天人合一</a> — 对境不住是天人合一的心态基础：知道万物一体，自然不会为一己得失动心</li><li><a href="/10-核心模型/model-自然务实">自然务实</a> — 对境不住在日常生活中的应用</li><li><a href="/10-核心模型/model-历境炼心">历境炼心</a> — 对境不住是&quot;防守&quot;（保持清净），历境炼心是&quot;进攻&quot;（把烦恼变觉悟）</li><li><a href="/10-核心模型/model-圆融中和">圆融中和</a> — 对境不住才能客观判断、不走极端</li></ul><hr><h2 id="来源文章" tabindex="-1">来源文章 <a class="header-anchor" href="#来源文章" aria-label="Permalink to &quot;来源文章&quot;">​</a></h2><ul><li>金刚经第1分（法会由分）</li><li>金刚经第2分（善现启请分）</li><li>金刚经第3分（大乘正宗分）</li><li>金刚经第4分（妙行无住分）</li><li>金刚经第5分（如理实见分）</li><li>金刚经第6分（正信希有分）</li><li>金刚经第7分（无得无说分）</li><li>金刚经第8分（依法出生分）</li><li>金刚经第9分（一相无相分）</li><li>金刚经第10分（庄严净土分）</li><li>金刚经第11分（无为福胜分）</li><li>金刚经第12分（尊重正教分）</li><li>金刚经第15分（持经功德分）</li><li>金刚经第16分（能净业障分）</li><li>金刚经第17分（究竟无我分）</li><li>金刚经第18分（一体同观分）</li><li>金刚经第19分（法界通化分）</li><li>金刚经第20分（离色离相分）</li><li>金刚经第23分（净心行善分）</li><li>金刚经第25分（化无所化分）</li><li>金刚经第26分（法身非相分）</li><li>金刚经第32分（应化非真分）</li><li>答疑专辑2014/2019</li><li>六祖法宝坛经</li><li>心经讲解</li><li>道德经讲解</li></ul><blockquote><p>来源：<a href="/01-Raw-Sources/1了空居士讲《金刚经》-第一分法会因由分20160909">1了空居士讲《金刚经》-第一分法会因由分20160909</a>、<a href="/01-Raw-Sources/10了空居士讲《金刚经》-第十分庄严净土分20161104">10了空居士讲《金刚经》-第十分庄严净土分20161104</a> 蒸馏日期：2026-05-05（第一版）2026-05-06（重构：21原子→16原子，6组分类，新增四步操作法、失败诊断、分阶实践指引）</p></blockquote>`,115)])])}const c=o(l,[["render",n]]);export{p as __pageData,c as default};
